def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    strong_opp = 0
    desperate_opp = 0
    rich_opp = 0

    for opp_id, opp in opponents_status.items():
        if not opp.get('alive', False):
            continue
        alive.append(opp)
        if opp.get('budget', 0) >= 120:
            rich_opp += 1
        if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
            desperate_opp += 1
        if opp.get('daily_salary', 0) >= DAILY_SALARY:
            strong_opp += 1
        prev = opp.get('previous_trace', {})
        bid = prev.get('bid') if isinstance(prev, dict) else None
        if bid is not None:
            prev_bids.append(float(bid))

    if not alive:
        if hp <= 2 or no_water_days >= 1:
            return float(min(budget, DAILY_SALARY * 0.75))
        return float(min(budget, DAILY_SALARY * 0.2))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0.0

    supply_pressure = 1.0 - ((supply - MIN_SUPPLY) / float(MAX_SUPPLY - MIN_SUPPLY))
    if supply_pressure < 0:
        supply_pressure = 0.0
    if supply_pressure > 1:
        supply_pressure = 1.0

    urgency = 0.0
    if hp <= 2:
        urgency += 0.55
    elif hp <= 4:
        urgency += 0.3
    if no_water_days >= 2:
        urgency += 0.35
    elif no_water_days >= 1:
        urgency += 0.2
    urgency += 0.2 * supply_pressure

    if highest_prev >= 150:
        base = DAILY_SALARY * 0.22
    elif highest_prev >= 110:
        base = DAILY_SALARY * 0.3
    elif highest_prev >= 70:
        base = min(DAILY_SALARY * 0.7, highest_prev * 0.72)
    elif highest_prev > 0:
        base = max(DAILY_SALARY * 0.42, highest_prev + 2.0)
    else:
        base = DAILY_SALARY * 0.4

    if rich_opp >= 2 and avg_prev > 100:
        base *= 0.85
    if desperate_opp >= 2:
        base *= 1.15
    if supply >= 22:
        base *= 0.82
    elif supply <= 17:
        base *= 1.18

    bid = base + DAILY_SALARY * urgency

    if hp <= 2 or no_water_days >= 2:
        floor_bid = DAILY_SALARY * 0.88
        if bid < floor_bid:
            bid = floor_bid

    if hp >= 7 and no_water_days == 0 and highest_prev >= 120 and supply >= 20:
        bid = min(bid, DAILY_SALARY * 0.28)

    max_safe = budget
    if hp > 4 and no_water_days == 0:
        max_safe = min(max_safe, budget * 0.55)
    elif hp > 2:
        max_safe = min(max_safe, budget * 0.75)

    bid = min(bid, max_safe)
    if bid < 0:
        bid = 0.0
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    supply = day_context['supply']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], 20.0)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if yesterday_bids:
        max_prev = max(yesterday_bids)
        if my_status['hp'] < 4:
            return min(my_status['budget'], max_prev + 10.0)
        if supply < 18:
            return min(my_status['budget'], max_prev + 5.0)
        return min(my_status['budget'], max_prev * 0.9)

    return min(my_status['budget'], DAILY_SALARY * 0.4)

def get_bid(day_context, my_status, opponents_status):
    # Constants
    WATER_REQ = 8
    DAILY_SALARY = 140
    MAX_BID = min(my_status['budget'], DAILY_SALARY * 0.95)

    # Determine how many units are available
    supply = int(day_context['supply'])
    max_units = supply // WATER_REQ

    # Collect alive opponents and their previous bids
    alive_opps = {oid: o for oid, o in opponents_status.items() if o['alive']}
    prev_bids = []
    for opp in alive_opps.values():
        trace = opp.get('previous_trace', {})
        if trace and 'bid' in trace and trace['bid'] is not None:
            prev_bids.append(trace['bid'])

    # Determine if we need water urgently
    need_water = my_status['hp'] <= 2 or my_status['no_water_days'] >= 2

    # Default bid if no previous data
    if not prev_bids:
        if need_water:
            return min(MAX_BID, DAILY_SALARY * 0.8)
        else:
            return min(my_status['budget'], DAILY_SALARY * 0.4)

    highest_prev = max(prev_bids)

    # If any opponent had a very high bid in previous meta-round, they may be aggressive
    if highest_prev >= DAILY_SALARY * 0.85:
        if need_water:
            # We must outbid but limited
            bid = max(highest_prev + 1.0, DAILY_SALARY * 0.85)
            return min(MAX_BID, bid)
        else:
            # Avoid bidding war, stay low
            return min(my_status['budget'], DAILY_SALARY * 0.35)

    # Moderate opponents: we can try to outbid slightly
    if need_water:
        target = max(highest_prev + 1.5, DAILY_SALARY * 0.6)
        return min(MAX_BID, target)
    else:
        # Conservative when not desperate
        target = max(highest_prev + 1.0, DAILY_SALARY * 0.45)
        return min(my_status['budget'], target)
